function validate([image, sr, sc, color]) {
  if (!Array.isArray(image) || image.length < 1 || image.length > 50) return 'image needs 1 to 50 rows.';
  const n = image[0].length;
  if (n < 1 || n > 50) return 'image needs 1 to 50 columns.';
  if (image.some(row => !Array.isArray(row) || row.length !== n)) return 'Every row must have the same length.';
  if (image.some(row => row.some(v => !Number.isInteger(v) || v < 0 || v >= 65536))) return 'Pixel values are integers from 0 to 65535.';
  if (!Number.isInteger(color) || color < 0 || color >= 65536) return 'color is an integer from 0 to 65535.';
  if (!Number.isInteger(sr) || sr < 0 || sr >= image.length) return 'sr must be a row of image.';
  if (!Number.isInteger(sc) || sc < 0 || sc >= n) return 'sc must be a column of image.';
  return null;
}

