function floodFill(image, sr, sc, color) {
  const m = image.length, n = image[0].length, start = image[sr][sc];
  const reached = image.map(row => row.map(() => false));
  reached[sr][sc] = true;
  let changed = true;
  while (changed) {
    changed = false;
    for (let i = 0; i < m; i++)
      for (let j = 0; j < n; j++) {
        if (reached[i][j] || image[i][j] !== start) continue;
        const touch = (i > 0 && reached[i - 1][j]) || (i < m - 1 && reached[i + 1][j]) || (j > 0 && reached[i][j - 1]) || (j < n - 1 && reached[i][j + 1]);
        if (touch) { reached[i][j] = true; changed = true; }
      }
  }
  return image.map((row, i) => row.map((v, j) => (reached[i][j] ? color : v)));
}

