function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const m = int(1, 5), n = int(1, 5), k = int(1, 3);
    const image = Array.from({ length: m }, () => Array.from({ length: n }, () => int(0, k - 1)));
    const sr = int(0, m - 1), sc = int(0, n - 1);
    const color = rand() < 0.25 ? image[sr][sc] : int(0, 3);
    return [image, sr, sc, color];
  }
  const m = int(40, 50), n = int(40, 50);
  const style = int(0, 2);
  let image;
  if (style === 0) {
    // A winding corridor of 7s between walls of 0s, so the fill must follow one long path.
    image = Array.from({ length: m }, (_, i) => Array.from({ length: n }, (_, j) => (i % 2 === 0 || (i % 4 === 1 && j === n - 1) || (i % 4 === 3 && j === 0) ? 7 : 0)));
  } else {
    const wall = style === 1 ? 0.3 : 0.45;
    image = Array.from({ length: m }, () => Array.from({ length: n }, () => (rand() < wall ? int(0, 65535) : 7)));
  }
  const sr = style === 0 ? 0 : int(0, m - 1), sc = style === 0 ? 0 : int(0, n - 1);
  return [image, sr, sc, rand() < 0.1 ? image[sr][sc] : int(0, 65535)];
}
